"use strict";(self.webpackChunkciroh_docuhub=self.webpackChunkciroh_docuhub||[]).push([["56435"],{77548(e){e.exports=JSON.parse('{"id":"fim","title":"Flood Inundation Mapping Working Group","description":"Cultivates a vibrant Community of Practice among CIROH researchers and federal partners, providing thought leadership by synthesizing CIROH\'s advancements in FIM and aligning them with broader developments in the FIM research community. Serves as a key advocate for FIM within CIROH, informing strategic direction and CIROH roadmap development.","leads":["Sagy Cohen, University of Alabama"],"reportsCollectionId":"","annual":{"period":"2025-2026","objectives":["Analyze CIROH\'s research portfolio and the broader research community FIM research. Provide input for roadmaps, governance documents, and documentation for CIROH\'s community FIM products.","Develop a scholarly product (e.g., journal article, special issue in a high-profile journal, conference session) spotlighting CIROH\'s research advances in large-domain FIM.","Initiate discussions with the CIROH R2X team and OWP personnel toward the development of a FIM-centric R2O transition roadmap.","Support FIM-related education and training opportunities, including webinars, DevCon workshops, hackathons, and Summer Institute participation."],"accomplishments":["Monthly virtual meeting, and two in-person meetings (during DevCon26 and Science Meeting)","Six (6) seminar presentations by group members (Objective #4)","Two (2) presentations by OWP staff on research efforts and operational tools (Objectives #4 & #3)","Identification of six (6) training workshops for the FIM track in the 2026 CIROH Developers Conference (Objective #4)","Development of a large overview paper involving over a dozen WG members (Objective #2)"],"products":["The CIROH Community FIM Ecosystem: https://hub.ciroh.org/docs/products/community-fim/"]}}')}}]);